//! Cross-library validation gates against RDKit, tblite and ASE.
//!
//! Fichas F81 (CIP stereochemistry), F82 (ML descriptors + Ertl TPSA),
//! F83 (canonical SMILES), F84 (ALPB solvation) and F85 (variable-cell
//! stress).
//!
//! These tests consume the fixtures generated by the oracles in
//! `scripts/validation/` (RDKit / tblite / ASE references) and recompute the
//! sci-form side, so CI validates real cross-library agreement without
//! installing any of those tools.
//!
//! Regenerate the fixtures with:
//! ```bash
//! python scripts/validation/oracle_rdkit_chem.py all
//! python scripts/validation/oracle_tblite.py alpb
//! python scripts/validation/oracle_ase.py
//! ```

use std::collections::BTreeMap;
use std::path::PathBuf;

use serde::Deserialize;

fn fixture_path(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("validation")
        .join(name)
}

fn load<T: for<'de> Deserialize<'de>>(name: &str) -> T {
    let path = fixture_path(name);
    let data = std::fs::read_to_string(&path).unwrap_or_else(|err| {
        panic!(
            "missing fixture {} ({err}); run `scripts/run_validation.sh` (or the matching oracle)",
            path.display()
        )
    });
    serde_json::from_str(&data).expect("invalid fixture JSON")
}

/// Write the measured metric to `target/validation/{ficha}.json` so
/// `scripts/validation/collect.py` can merge it into the human-readable
/// `reports/validation/summary.json` after the test run.
fn record(
    ficha: &str,
    observable: &str,
    metric: &str,
    value: f64,
    tolerance: f64,
    passed: bool,
    n_cases: usize,
) {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("target")
        .join("validation");
    let _ = std::fs::create_dir_all(&dir);
    let payload = serde_json::json!({
        "ficha": ficha,
        "observable": observable,
        "metric": metric,
        "value": value,
        "tolerance": tolerance,
        "pass": passed,
        "n_cases": n_cases,
        "source": "tests/rdkit_chem_parity.rs",
    });
    // Merge with any rows already recorded for this ficha (a ficha can carry
    // several observables) and replace a previous row with the same key.
    let path = dir.join(format!("{ficha}.json"));
    let mut rows: Vec<serde_json::Value> = std::fs::read_to_string(&path)
        .ok()
        .and_then(|text| serde_json::from_str::<serde_json::Value>(&text).ok())
        .map(|value| match value {
            serde_json::Value::Array(items) => items,
            other => vec![other],
        })
        .unwrap_or_default();
    rows.retain(|row| row.get("observable").and_then(|v| v.as_str()) != Some(observable));
    rows.push(payload);
    let _ = std::fs::write(&path, serde_json::Value::Array(rows).to_string());
}

/// Split a flat coordinate array into `[f64; 3]` positions.
fn positions_from(coords: &[f64]) -> Vec<[f64; 3]> {
    coords.chunks_exact(3).map(|c| [c[0], c[1], c[2]]).collect()
}

/// Bond-order encoding used by the `ml::compute_descriptors` /
/// `ml::compute_tpsa` APIs: 1 = single, 2 = double, 3 = triple,
/// 4 = aromatic.
fn bond_order_code(order: sci_form::graph::BondOrder) -> u8 {
    use sci_form::graph::BondOrder::*;
    match order {
        Single => 1,
        Double => 2,
        Triple => 3,
        Aromatic => 4,
        Unknown => 1,
        // `BondOrder` is `#[non_exhaustive]`: a bond order added after this
        // test was written maps to 1, the same as `Unknown`.
        _ => 1,
    }
}

/// `(elements, bonds)` arrays of a parsed molecule, using the bond-order
/// encoding above.
fn graph_arrays(mol: &sci_form::graph::Molecule) -> (Vec<u8>, Vec<(usize, usize, u8)>) {
    let elements: Vec<u8> = (0..mol.graph.node_count())
        .map(|i| mol.graph[petgraph::graph::NodeIndex::new(i)].element)
        .collect();
    let bonds: Vec<(usize, usize, u8)> = mol
        .graph
        .edge_indices()
        .map(|e| {
            let (a, b) = mol.graph.edge_endpoints(e).unwrap();
            (a.index(), b.index(), bond_order_code(mol.graph[e].order))
        })
        .collect();
    (elements, bonds)
}

/// Heavy-atom-only view of a parsed molecule.
fn heavy_view(elements: &[u8], bonds: &[(usize, usize, u8)]) -> (Vec<u8>, Vec<(usize, usize, u8)>) {
    let mut mapping = vec![usize::MAX; elements.len()];
    let mut heavy_elements = Vec::new();
    for (i, &z) in elements.iter().enumerate() {
        if z != 1 {
            mapping[i] = heavy_elements.len();
            heavy_elements.push(z);
        }
    }
    let heavy_bonds: Vec<(usize, usize, u8)> = bonds
        .iter()
        .filter(|(i, j, _)| elements[*i] != 1 && elements[*j] != 1)
        .map(|(i, j, o)| (mapping[*i], mapping[*j], *o))
        .collect();
    (heavy_elements, heavy_bonds)
}

/// Per-atom "is aromatic" flags taken from sci-form's own perception.
fn aromatic_flags(mol: &sci_form::graph::Molecule) -> Vec<bool> {
    (0..mol.graph.node_count())
        .map(|i| {
            let node = petgraph::graph::NodeIndex::new(i);
            mol.graph
                .edges(node)
                .any(|e| matches!(e.weight().order, sci_form::graph::BondOrder::Aromatic))
        })
        .collect()
}

// ═══════════════════════════════════════════════════════════════════════════
// F81 — CIP stereochemistry vs RDKit
// ═══════════════════════════════════════════════════════════════════════════

mod f81_stereo {
    use super::*;
    use sci_form::stereo::analyze_stereo;

    #[derive(Deserialize)]
    struct Case {
        name: String,
        smiles: String,
        feature: String,
        #[allow(dead_code)]
        mirrored: bool,
        elements: Vec<u8>,
        coords: Vec<f64>,
        rdkit_centers_from_3d: Vec<(usize, String)>,
        rdkit_bonds_from_3d: Vec<(usize, usize, String)>,
        rdkit_centers_from_tag: Vec<(usize, String)>,
        #[allow(dead_code)]
        rdkit_bonds_from_tag: Vec<(usize, usize, String)>,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// sci-form must assign the same R/S label as RDKit for every
    /// stereocentre RDKit labels from the *same* 3-D geometry, and the same
    /// E/Z label for every double bond.
    #[test]
    fn f81_cip_stereo_labels_match_rdkit() {
        let fixture: Fixture = load("rdkit_stereo.json");
        assert!(fixture.cases.len() >= 15, "corpus too small");

        let mut mismatches: Vec<String> = Vec::new();
        let mut compared_centers = 0usize;
        let mut compared_bonds = 0usize;

        for case in &fixture.cases {
            let mol = match sci_form::parse(&case.smiles) {
                Ok(mol) => mol,
                Err(err) => {
                    mismatches.push(format!("{}: parse failed: {err}", case.name));
                    continue;
                }
            };
            // The sci-form graph must match the RDKit atom list (heavy atoms
            // first, then the implicit hydrogens in the same order).
            let our_elements: Vec<u8> = (0..mol.graph.node_count())
                .map(|i| mol.graph[petgraph::graph::NodeIndex::new(i)].element)
                .collect();
            if our_elements != case.elements {
                mismatches.push(format!(
                    "{}: atom list differs ({} atoms vs {})",
                    case.name,
                    our_elements.len(),
                    case.elements.len()
                ));
                continue;
            }

            let positions = positions_from(&case.coords);
            let analysis = analyze_stereo(&mol, &positions);

            // --- stereocentres -------------------------------------------
            let ours: BTreeMap<usize, Option<String>> = analysis
                .stereocenters
                .iter()
                .map(|sc| (sc.atom_index, sc.configuration.clone()))
                .collect();
            for (idx, label) in &case.rdkit_centers_from_3d {
                compared_centers += 1;
                match ours.get(idx) {
                    Some(Some(cfg)) if cfg == label => {}
                    Some(Some(cfg)) => mismatches.push(format!(
                        "{}: centre {idx}: sci-form {cfg} vs RDKit {label}",
                        case.name
                    )),
                    Some(None) => mismatches.push(format!(
                        "{}: centre {idx}: sci-form has no configuration (RDKit {label})",
                        case.name
                    )),
                    None => mismatches.push(format!(
                        "{}: centre {idx} not detected by sci-form (RDKit {label})",
                        case.name
                    )),
                }
            }

            // --- double bonds --------------------------------------------
            let ours_bonds: BTreeMap<(usize, usize), Option<String>> = analysis
                .double_bonds
                .iter()
                .map(|db| {
                    let key = if db.atom1 <= db.atom2 {
                        (db.atom1, db.atom2)
                    } else {
                        (db.atom2, db.atom1)
                    };
                    (key, db.configuration.clone())
                })
                .collect();
            for (i, j, label) in &case.rdkit_bonds_from_3d {
                compared_bonds += 1;
                let key = if i <= j { (*i, *j) } else { (*j, *i) };
                match ours_bonds.get(&key) {
                    Some(Some(cfg)) if cfg == label => {}
                    Some(Some(cfg)) => mismatches.push(format!(
                        "{}: bond {i}-{j}: sci-form {cfg} vs RDKit {label}",
                        case.name
                    )),
                    Some(None) => mismatches.push(format!(
                        "{}: bond {i}-{j}: sci-form has no configuration (RDKit {label})",
                        case.name
                    )),
                    None => mismatches.push(format!(
                        "{}: bond {i}-{j} not detected by sci-form (RDKit {label})",
                        case.name
                    )),
                }
            }

            // --- structural features -------------------------------------
            match case.feature.as_str() {
                "allene" if analysis.helical_chirality.is_empty() => {
                    mismatches.push(format!(
                        "{}: no helical (allene) chirality found",
                        case.name
                    ));
                }
                "atropisomer" if analysis.atropisomeric_axes.is_empty() => {
                    mismatches.push(format!("{}: no atropisomeric axis found", case.name));
                }
                _ => {}
            }
        }

        assert!(
            compared_centers >= 10,
            "too few stereocentres compared: {compared_centers}"
        );
        assert!(
            compared_bonds >= 8,
            "too few double bonds compared: {compared_bonds}"
        );
        assert!(
            mismatches.is_empty(),
            "{} / {} stereo mismatches vs RDKit: {:?}",
            mismatches.len(),
            fixture.cases.len(),
            &mismatches[..mismatches.len().min(20)]
        );

        println!(
            "F81 CIP stereo: {} centres, {} double bonds, 0 mismatches",
            compared_centers, compared_bonds
        );
        record(
            "F81",
            "cip_stereo_labels_vs_rdkit",
            "mismatched_labels",
            0.0,
            0.0,
            true,
            compared_centers + compared_bonds,
        );
    }

    /// sci-form must be able to consume a SMILES that carries `@`/`@@` tags,
    /// and — because it is a 3-D driven analyser — it must derive the label
    /// from the coordinates, *ignoring* the tag.  The "mirrored" cases prove
    /// this: the same SMILES tag with a mirrored geometry must flip the
    /// sci-form label while RDKit's tag-derived label stays put.
    #[test]
    fn f81_smiles_chiral_tags_are_parsed_and_3d_driven() {
        let fixture: Fixture = load("rdkit_stereo.json");
        let mut problems: Vec<String> = Vec::new();
        let mut checked = 0usize;

        for case in &fixture.cases {
            // Every corpus SMILES must parse (they all carry @/@@ or /,\ tags
            // for part of the corpus).
            let mol = match sci_form::parse(&case.smiles) {
                Ok(mol) => mol,
                Err(err) => {
                    problems.push(format!("{}: parse failed: {err}", case.name));
                    continue;
                }
            };
            if case.rdkit_centers_from_tag.is_empty() {
                continue;
            }
            let positions = positions_from(&case.coords);
            let analysis = analyze_stereo(&mol, &positions);
            let ours: BTreeMap<usize, Option<String>> = analysis
                .stereocenters
                .iter()
                .map(|sc| (sc.atom_index, sc.configuration.clone()))
                .collect();

            for (idx, tag_label) in &case.rdkit_centers_from_tag {
                let from_3d = case
                    .rdkit_centers_from_3d
                    .iter()
                    .find(|(i, _)| i == idx)
                    .map(|(_, l)| l.clone());
                let ours_label = ours.get(idx).cloned().flatten();
                checked += 1;
                match (from_3d.clone(), ours_label.clone()) {
                    (Some(ref3d), Some(ours)) => {
                        if ours != ref3d {
                            problems.push(format!(
                                "{}: centre {idx}: sci-form {ours} != RDKit(3-D) {ref3d}",
                                case.name
                            ));
                        }
                        // When the 3-D configuration and the SMILES tag
                        // disagree (the mirrored cases) sci-form must follow
                        // the 3-D: a tag-driven implementation would return
                        // `tag_label` instead.
                        if ref3d != *tag_label && ours == *tag_label {
                            problems.push(format!(
                                "{}: centre {idx}: sci-form followed the SMILES tag \
                                 ({tag_label}) instead of the 3-D geometry ({ref3d})",
                                case.name
                            ));
                        }
                    }
                    _ => problems.push(format!(
                        "{}: centre {idx}: sci-form produced no label (RDKit 3-D {:?})",
                        case.name, from_3d
                    )),
                }
            }
        }

        assert!(
            checked >= 8,
            "too few tagged stereocentres checked: {checked}"
        );
        assert!(
            problems.is_empty(),
            "{} tag/3-D problems: {:?}",
            problems.len(),
            &problems[..problems.len().min(8)]
        );
        println!("F81 chiral tags: {checked} tagged centres parsed and 3-D driven");
        record(
            "F81",
            "smiles_chiral_tag_handling",
            "mismatched_cases",
            0.0,
            0.0,
            true,
            checked,
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F82 — ML descriptors + Ertl TPSA vs RDKit
// ═══════════════════════════════════════════════════════════════════════════

mod f82_descriptors {
    use super::*;
    use sci_form::ml::{compute_descriptors, compute_tpsa};

    #[derive(Deserialize)]
    struct Case {
        smiles: String,
        elements_with_h: Vec<u8>,
        #[allow(dead_code)]
        n_heavy: usize,
        n_hydrogens: usize,
        n_bonds_with_h: usize,
        mol_wt: f64,
        heavy_atom_count: usize,
        num_hbd: usize,
        num_hba: usize,
        num_rotatable_strict: usize,
        num_rotatable_nonstrict: usize,
        fraction_csp3: f64,
        num_rings: usize,
        n_sssr: usize,
        num_aromatic_atoms: usize,
        wiener_index: f64,
        balaban_j: f64,
        #[allow(dead_code)]
        tpsa: f64,
        tpsa_with_s_p: f64,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// Descriptors whose sci-form and RDKit definitions are equivalent and
    /// are therefore gated; descriptors with a different (documented)
    /// definition are only reported.
    #[test]
    fn f82_ml_descriptors_match_rdkit() {
        let fixture: Fixture = load("rdkit_descriptors.json");
        assert!(fixture.cases.len() >= 200, "corpus too small");

        // Gated deviations.
        let mut d_mw = 0.0f64;
        let mut d_counts = 0.0f64;
        let mut d_fsp3 = 0.0f64;
        let mut d_wiener = 0.0f64;
        let mut d_balaban = 0.0f64;
        let mut d_tpsa = 0.0f64;
        // Reported (definitionally different) deviations.
        let mut d_hbd = 0.0f64;
        let mut d_hba = 0.0f64;
        let mut d_rot_full = 0.0f64;
        let mut d_rot_heavy = 0.0f64;
        let mut d_rings_sym = 0.0f64;
        let mut d_aromatic_atoms = 0.0f64;
        let mut d_tpsa_no_sp = 0.0f64;

        let mut compared = 0usize;
        let mut skipped = 0usize;
        let mut excluded_aromatic: Vec<String> = Vec::new();
        let mut excluded_charged: Vec<String> = Vec::new();
        let mut ring_mismatch: Vec<String> = Vec::new();
        let mut arom_mismatch: Vec<String> = Vec::new();

        for case in &fixture.cases {
            let mol = match sci_form::parse(&case.smiles) {
                Ok(mol) => mol,
                Err(_) => {
                    skipped += 1;
                    continue;
                }
            };
            let (elements, bonds) = graph_arrays(&mol);
            if elements != case.elements_with_h {
                // Different implicit-hydrogen count than RDKit: the molecule
                // is not comparable atom by atom (reported by F01).
                skipped += 1;
                continue;
            }
            compared += 1;

            let flags = aromatic_flags(&mol);
            let full = compute_descriptors(&elements, &bonds, &[], &flags);
            let (heavy_elements, heavy_bonds) = heavy_view(&elements, &bonds);
            let heavy = compute_descriptors(&heavy_elements, &heavy_bonds, &[], &[]);

            d_mw = d_mw.max((full.molecular_weight - case.mol_wt).abs());
            d_counts = d_counts
                .max((full.n_heavy_atoms as f64 - case.heavy_atom_count as f64).abs())
                .max((full.n_hydrogens as f64 - case.n_hydrogens as f64).abs())
                .max((full.n_bonds as f64 - case.n_bonds_with_h as f64).abs());
            d_fsp3 = d_fsp3.max((full.fsp3 - case.fraction_csp3).abs());
            d_wiener = d_wiener.max((heavy.wiener_index - case.wiener_index).abs());

            d_hbd = d_hbd.max((full.n_hbd as f64 - case.num_hbd as f64).abs());
            d_hba = d_hba.max((full.n_hba as f64 - case.num_hba as f64).abs());
            d_rot_full = d_rot_full
                .max((full.n_rotatable_bonds as f64 - case.num_rotatable_strict as f64).abs());
            d_rot_heavy = d_rot_heavy
                .max((heavy.n_rotatable_bonds as f64 - case.num_rotatable_nonstrict as f64).abs());
            d_rings_sym = d_rings_sym.max((full.n_rings as f64 - case.num_rings as f64).abs());
            d_aromatic_atoms = d_aromatic_atoms
                .max((full.n_aromatic as f64 - case.num_aromatic_atoms as f64).abs());
            d_tpsa_no_sp = d_tpsa_no_sp.max((compute_tpsa(&elements, &bonds) - case.tpsa).abs());

            if full.n_rings != case.n_sssr {
                ring_mismatch.push(format!(
                    "{}: rings {} != SSSR size {}",
                    case.smiles, full.n_rings, case.n_sssr
                ));
            }
            if full.n_aromatic != case.num_aromatic_atoms {
                arom_mismatch.push(format!(
                    "{}: aromatic atoms {} != {}",
                    case.smiles, full.n_aromatic, case.num_aromatic_atoms
                ));
            }

            // The TPSA fragment table and the Balaban J index both depend on
            // the perceived aromaticity and (for charged atoms) on the formal
            // charge, neither of which the `compute_tpsa(elements, bonds)`
            // API can see.  Molecules where sci-form's aromaticity
            // perception differs from RDKit's, or that carry a charged
            // polar atom, are therefore excluded from the TPSA gate and
            // listed explicitly.
            let charged_polar = (0..mol.graph.node_count()).any(|i| {
                let node = petgraph::graph::NodeIndex::new(i);
                let atom = &mol.graph[node];
                atom.formal_charge != 0 && matches!(atom.element, 7 | 8 | 15 | 16)
            });
            let arom_differs = full.n_aromatic != case.num_aromatic_atoms;
            if arom_differs {
                excluded_aromatic.push(case.smiles.clone());
            }
            if charged_polar {
                excluded_charged.push(case.smiles.clone());
            }
            if !arom_differs {
                // The Balaban J index is bond-order weighted: an aromaticity
                // perception difference changes the weights.
                d_balaban = d_balaban.max((heavy.balaban_j - case.balaban_j).abs());
            }
            if !arom_differs && !charged_polar {
                let tpsa = compute_tpsa(&elements, &bonds);
                d_tpsa = d_tpsa.max((tpsa - case.tpsa_with_s_p).abs());
            }
        }

        println!(
            "F82 descriptors: compared={compared} skipped={skipped}\n  \
             GATED    MW d={:.2e} Da | counts d={:.0} | Fsp3 d={:.2e} | Wiener d={:.0} | \
             BalabanJ d={:.2e} | TPSA d={:.4} A^2\n  \
             REPORTED HBD d={:.0} | HBA d={:.0} | rotatable(full/strict) d={:.0}, \
             (heavy/non-strict) d={:.0} | rings vs CalcNumRings d={:.0} | aromatic atoms d={:.0} | \
             TPSA(N/O only, RDKit default) d={:.1}\n  \
             excluded from TPSA: {} aromaticity mismatches, {} charged polar atoms",
            d_mw,
            d_counts,
            d_fsp3,
            d_wiener,
            d_balaban,
            d_tpsa,
            d_hbd,
            d_hba,
            d_rot_full,
            d_rot_heavy,
            d_rings_sym,
            d_aromatic_atoms,
            d_tpsa_no_sp,
            excluded_aromatic.len(),
            excluded_charged.len()
        );

        assert!(compared >= 200, "too few comparable cases: {compared}");
        assert!(d_mw <= 1e-6, "MW deviation {:.6} Da", d_mw);
        assert!(d_counts <= 0.0, "atom/bond count deviation {}", d_counts);
        assert!(d_fsp3 <= 1e-12, "Fsp3 deviation {:.3e}", d_fsp3);
        assert!(d_wiener <= 0.0, "Wiener index deviation {}", d_wiener);
        assert!(d_balaban <= 1e-9, "Balaban J deviation {:.3e}", d_balaban);
        assert!(d_tpsa <= 0.01, "TPSA deviation {:.4} A^2", d_tpsa);
        assert!(
            ring_mismatch.is_empty(),
            "{} ring-count mismatches vs the rank-sized SSSR: {:?}",
            ring_mismatch.len(),
            &ring_mismatch[..ring_mismatch.len().min(5)]
        );

        record(
            "F82",
            "ml_descriptors_max_abs",
            "max_abs",
            d_mw.max(d_fsp3).max(d_balaban).max(d_tpsa),
            0.01,
            true,
            compared,
        );
        record(
            "F82",
            "ertl_tpsa_max_abs",
            "max_abs",
            d_tpsa,
            0.01,
            true,
            compared,
        );
        record(
            "F82",
            "hba_definition_difference",
            "max_abs",
            d_hba,
            d_hba,
            true,
            compared,
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F83 — canonical SMILES vs RDKit
// ═══════════════════════════════════════════════════════════════════════════

mod f83_canonical {
    use super::*;
    use sci_form::canonical_smiles::to_canonical_smiles;

    #[derive(Deserialize)]
    struct Case {
        name: String,
        smiles: String,
        rdkit_canonical: String,
        #[allow(dead_code)]
        rdkit_canonical_reordered: Option<String>,
        rdkit_canonical_reorderings: Vec<String>,
        n_heavy_atoms: usize,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// Bond multiset of a parsed molecule (heavy atoms only), used to check
    /// that sci-form's canonical SMILES describes the same molecule.
    fn heavy_bond_multiset(mol: &sci_form::graph::Molecule) -> Vec<(u8, u8, u8)> {
        let mut out: Vec<(u8, u8, u8)> = mol
            .graph
            .edge_indices()
            .filter_map(|e| {
                let (a, b) = mol.graph.edge_endpoints(e).unwrap();
                let ea = mol.graph[a].element;
                let eb = mol.graph[b].element;
                if ea == 1 || eb == 1 {
                    return None;
                }
                let order = match mol.graph[e].order {
                    sci_form::graph::BondOrder::Single => 1,
                    sci_form::graph::BondOrder::Double => 2,
                    sci_form::graph::BondOrder::Triple => 3,
                    sci_form::graph::BondOrder::Aromatic => 4,
                    sci_form::graph::BondOrder::Unknown => 1,
                    // `BondOrder` is `#[non_exhaustive]`: a bond order added
                    // after this test was written maps to 1, the same as
                    // `Unknown`.
                    _ => 1,
                };
                Some((ea.min(eb), ea.max(eb), order))
            })
            .collect();
        out.sort_unstable();
        out
    }

    /// sci-form's canonical SMILES must
    ///  (a) re-parse to the same molecule,
    ///  (b) be idempotent, and
    ///  (c) be invariant under a reordering of the input atoms.
    ///
    /// The number of molecules whose canonical string is *identical* to
    /// RDKit's is reported (a different but equally valid canonical form is
    /// a legitimate outcome and is not gated).
    #[test]
    fn f83_canonical_smiles_roundtrip_and_reordering_invariant() {
        let fixture: Fixture = load("rdkit_canonical_smiles.json");
        assert!(fixture.cases.len() >= 30, "corpus too small");

        let mut problems: Vec<String> = Vec::new();
        let mut identical_to_rdkit = 0usize;
        let mut compared = 0usize;

        for case in &fixture.cases {
            let mol = match sci_form::parse(&case.smiles) {
                Ok(mol) => mol,
                Err(err) => {
                    problems.push(format!("{}: parse failed: {err}", case.name));
                    continue;
                }
            };
            let canonical = to_canonical_smiles(&mol);
            if canonical.is_empty() {
                problems.push(format!("{}: empty canonical SMILES", case.name));
                continue;
            }
            compared += 1;
            if canonical == case.rdkit_canonical {
                identical_to_rdkit += 1;
            }

            // (a) round trip: the canonical SMILES must re-parse to the same
            // molecule.
            let reparsed = match sci_form::parse(&canonical) {
                Ok(m) => m,
                Err(err) => {
                    problems.push(format!(
                        "{}: canonical SMILES {canonical:?} does not re-parse: {err}",
                        case.name
                    ));
                    continue;
                }
            };
            let n_heavy = (0..reparsed.graph.node_count())
                .filter(|&i| reparsed.graph[petgraph::graph::NodeIndex::new(i)].element != 1)
                .count();
            if n_heavy != case.n_heavy_atoms {
                problems.push(format!(
                    "{}: canonical SMILES has {n_heavy} heavy atoms, expected {}",
                    case.name, case.n_heavy_atoms
                ));
            }
            if heavy_bond_multiset(&reparsed) != heavy_bond_multiset(&mol) {
                problems.push(format!(
                    "{}: canonical SMILES {canonical:?} changes the bond multiset",
                    case.name
                ));
            }
            // (b) idempotence.
            let again = to_canonical_smiles(&reparsed);
            if again != canonical {
                problems.push(format!(
                    "{}: canonical SMILES is not idempotent ({canonical:?} -> {again:?})",
                    case.name
                ));
            }

            // (c) invariance under input atom reordering.
            for reordered in &case.rdkit_canonical_reorderings {
                if let Ok(mol2) = sci_form::parse(reordered) {
                    let canonical2 = to_canonical_smiles(&mol2);
                    if canonical2 != canonical {
                        problems.push(format!(
                            "{}: canonical SMILES depends on the input atom order \
                             ({canonical:?} vs {canonical2:?})",
                            case.name
                        ));
                    }
                }
            }
        }

        println!(
            "F83 canonical SMILES: compared={compared}, identical to RDKit: {identical_to_rdkit}/{}",
            fixture.cases.len()
        );
        assert!(compared >= 30, "too few comparable cases: {compared}");
        assert!(
            problems.is_empty(),
            "{} / {} canonical SMILES problems: {:?}",
            problems.len(),
            fixture.cases.len(),
            &problems[..problems.len().min(10)]
        );

        record(
            "F83",
            "canonical_smiles_roundtrip_reordering",
            "mismatched_cases",
            0.0,
            0.0,
            true,
            compared,
        );
        // Reported (not gated): sci-form and RDKit use different
        // canonicalisation algorithms, so the strings coincide only for the
        // molecules whose canonical form is unique.
        let fraction = identical_to_rdkit as f64 / compared as f64;
        record(
            "F83",
            "canonical_smiles_identical_to_rdkit",
            "fraction_identical",
            fraction,
            fraction,
            true,
            compared,
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F84 — ALPB solvation vs tblite
// ═══════════════════════════════════════════════════════════════════════════

mod f84_alpb {
    use super::*;
    use sci_form::solvation_alpb::{compute_alpb_solvation, compute_born_radii, AlpbConfig};
    use sci_form::surface::sasa::compute_sasa;

    #[derive(Deserialize)]
    struct Case {
        name: String,
        #[allow(dead_code)]
        kind: String,
        elements: Vec<u8>,
        coords: Vec<f64>,
        charges: Vec<f64>,
        gb_kcal: f64,
        #[allow(dead_code)]
        gbe_kcal: f64,
        alpb_kcal: f64,
        gbsa_kcal: f64,
    }

    #[derive(Deserialize)]
    struct Fixture {
        solvent_dielectric: f64,
        cases: Vec<Case>,
    }

    /// sci-form's ALPB electrostatic term must agree with tblite's
    /// non-empirical generalised-Born solvation (epsilon = 78.5, Born model
    /// "still") evaluated with the *same* GFN2-xTB charges and the same
    /// geometry.
    ///
    /// The total solvation energies and the individual Born radii are
    /// reported but not gated: tblite's parametrized ALPB/GBSA('water')
    /// additionally contains the charge-dependent solvation (CDS) term and an
    /// empirical shift, and the tblite Python API does not expose the Born
    /// radii.
    #[test]
    fn f84_alpb_solvation_matches_tblite() {
        let fixture: Fixture = load("tblite_alpb.json");
        assert!(fixture.cases.len() >= 12, "corpus too small");

        let config = AlpbConfig {
            solvent_dielectric: fixture.solvent_dielectric,
            ..AlpbConfig::default()
        };

        let mut worst_electrostatic = (0.0f64, String::new());
        let mut worst_total = (0.0f64, String::new());
        let mut worst_nonpolar_consistency = 0.0f64;

        for case in &fixture.cases {
            let positions = positions_from(&case.coords);
            let result = compute_alpb_solvation(&case.elements, &positions, &case.charges, &config)
                .expect("valid input");
            let born = compute_born_radii(&case.elements, &positions, config.probe_radius)
                .expect("valid input");

            // The Born radii must be positive and larger than the intrinsic
            // radii (the descreening can only *increase* the effective
            // radius).
            for (k, &r) in born.radii.iter().enumerate() {
                assert!(
                    r > born.intrinsic[k] && r < 100.0,
                    "{}: atom {k} Born radius {r} (intrinsic {})",
                    case.name,
                    born.intrinsic[k]
                );
            }

            let delta = (result.electrostatic_energy - case.gb_kcal).abs();
            if delta > worst_electrostatic.0 {
                worst_electrostatic = (delta, case.name.clone());
            }
            let total_delta = (result.total_energy - case.alpb_kcal).abs();
            if total_delta > worst_total.0 {
                worst_total = (total_delta, case.name.clone());
            }

            // The non-polar term must be exactly surface_tension x SASA.
            let sasa = compute_sasa(&case.elements, &positions, Some(config.probe_radius), None);
            let expected = config.surface_tension * sasa.total_sasa;
            worst_nonpolar_consistency =
                worst_nonpolar_consistency.max((result.nonpolar_energy - expected).abs());

            println!(
                "  {:<12} sci-form elec {:8.3} | tblite GB {:8.3} | d {:6.3} ||                  sci-form total {:8.3} | tblite ALPB {:8.3} | tblite GBSA {:8.3} | nonpolar {:7.4}",
                case.name,
                result.electrostatic_energy,
                case.gb_kcal,
                result.electrostatic_energy - case.gb_kcal,
                result.total_energy,
                case.alpb_kcal,
                case.gbsa_kcal,
                result.nonpolar_energy
            );
        }

        println!(
            "F84 ALPB vs tblite: n={} worst |Δ electrostatic| = {:.3} kcal/mol ({});              worst |Δ total| = {:.3} kcal/mol ({}); non-polar consistency {:.2e}",
            fixture.cases.len(),
            worst_electrostatic.0,
            worst_electrostatic.1,
            worst_total.0,
            worst_total.1,
            worst_nonpolar_consistency
        );

        assert!(
            worst_electrostatic.0 <= 5.0,
            "worst electrostatic deviation {:.3} kcal/mol for {} (tolerance 5.0)",
            worst_electrostatic.0,
            worst_electrostatic.1
        );
        assert!(
            worst_nonpolar_consistency <= 1e-12,
            "the non-polar term must be surface_tension x SASA (deviation {:.3e})",
            worst_nonpolar_consistency
        );

        record(
            "F84",
            "alpb_electrostatic_max_abs",
            "max_abs",
            worst_electrostatic.0,
            5.0,
            worst_electrostatic.0 <= 5.0,
            fixture.cases.len(),
        );
        // Reported (not gated): tblite's parametrized ALPB('water') adds the
        // charge-dependent solvation (CDS) term and an empirical shift that
        // sci-form's ALPB does not contain.
        record(
            "F84",
            "alpb_total_vs_tblite_alpb_reported",
            "max_abs",
            worst_total.0,
            worst_total.0,
            true,
            fixture.cases.len(),
        );
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// F85 — variable-cell stress vs ASE
// ═══════════════════════════════════════════════════════════════════════════

mod f85_stress {
    use super::*;
    use sci_form::materials::variable_cell::{
        cell_volume, numerical_stress, optimize_variable_cell, CellEnergyForceFn,
        VariableCellConfig,
    };

    #[derive(Deserialize)]
    struct Case {
        name: String,
        lattice: [[f64; 3]; 3],
        positions: Vec<[f64; 3]>,
        sigma: f64,
        epsilon: f64,
        rc: f64,
        energy_ev: f64,
        stress_ev_per_a3: [[f64; 3]; 3],
        relaxed_lattice: Vec<f64>,
        #[allow(dead_code)]
        relaxed_energy_ev: f64,
    }

    #[derive(Deserialize)]
    struct Fixture {
        cases: Vec<Case>,
    }

    /// Advance the lattice-translation counter.
    ///
    /// The last component runs fastest.  Returns `false` when the whole
    /// range has been visited.
    fn next_translation(t: &mut [i32; 3], n_max: &[i32; 3]) -> bool {
        let mut c = 2;
        loop {
            t[c] += 1;
            if t[c] <= n_max[c] {
                return true;
            }
            t[c] = -n_max[c];
            if c == 0 {
                return false;
            }
            c -= 1;
        }
    }

    /// Lennard-Jones energy and forces, reproducing the conventions of
    /// ASE's `ase.calculators.lj.LennardJones`:
    ///
    /// * the pair energy is shifted by `u(rc)` so that it is continuous at
    ///   the cutoff;
    /// * an atom interacts with its own periodic images with half weight
    ///   (the image pair appears only once in ASE's neighbour list while the
    ///   energy carries a factor 1/2).
    fn lj_energy_forces(
        positions: &[[f64; 3]],
        lattice: &[[f64; 3]; 3],
        sigma: f64,
        epsilon: f64,
        rc: f64,
    ) -> (f64, Vec<[f64; 3]>) {
        let n = positions.len();
        let volume = cell_volume(lattice).abs();
        let mut energy = 0.0f64;
        let mut forces = vec![[0.0f64; 3]; n];

        // Translation range that covers every image within the cutoff.
        let n_max: [i32; 3] = [0usize, 1, 2].map(|k| {
            let l = (k + 1) % 3;
            let m = (k + 2) % 3;
            let a = lattice[l];
            let b = lattice[m];
            let area = (a[1] * b[2] - a[2] * b[1]).abs()
                + (a[2] * b[0] - a[0] * b[2]).abs()
                + (a[0] * b[1] - a[1] * b[0]).abs();
            let h = if area > 1e-12 { volume / area } else { 1e9 };
            ((rc / h).ceil() as i32) + 1
        });

        let u_rc = 4.0 * epsilon * ((sigma / rc).powi(12) - (sigma / rc).powi(6));

        // Shift of one lattice vector.
        let mut shift = [[0.0f64; 3]; 3];
        for c in 0..3 {
            for k in 0..3 {
                shift[c][k] = lattice[c][k];
            }
        }

        for i in 0..n {
            for j in (i + 1)..n {
                let mut t = [-n_max[0], -n_max[1], -n_max[2]];
                loop {
                    let mut d = [0.0f64; 3];
                    for k in 0..3 {
                        let mut s = 0.0;
                        for c in 0..3 {
                            s += t[c] as f64 * shift[c][k];
                        }
                        d[k] = positions[j][k] + s - positions[i][k];
                    }
                    let r2 = d[0] * d[0] + d[1] * d[1] + d[2] * d[2];
                    if r2 < rc * rc && r2 > 1e-24 {
                        let c6 = (sigma * sigma / r2).powi(3);
                        let c12 = c6 * c6;
                        let u = 4.0 * epsilon * (c12 - c6);
                        let du = -24.0 * epsilon * (2.0 * c12 - c6) / r2;
                        energy += u - u_rc;
                        for k in 0..3 {
                            forces[i][k] += du * d[k];
                            forces[j][k] -= du * d[k];
                        }
                    }
                    if !next_translation(&mut t, &n_max) {
                        break;
                    }
                }
            }
            // Self interaction with the periodic images (half weight: the
            // image pair appears only once in ASE's neighbour list while the
            // energy carries a factor 1/2).
            let mut t = [-n_max[0], -n_max[1], -n_max[2]];
            loop {
                let mut d = [0.0f64; 3];
                let mut is_zero = true;
                for k in 0..3 {
                    let mut s = 0.0;
                    for c in 0..3 {
                        s += t[c] as f64 * shift[c][k];
                    }
                    d[k] = s;
                    if t[k] != 0 {
                        is_zero = false;
                    }
                }
                let r2 = d[0] * d[0] + d[1] * d[1] + d[2] * d[2];
                if !is_zero && r2 < rc * rc && r2 > 1e-24 {
                    let c6 = (sigma * sigma / r2).powi(3);
                    let c12 = c6 * c6;
                    let u = 4.0 * epsilon * (c12 - c6);
                    let du = -24.0 * epsilon * (2.0 * c12 - c6) / r2;
                    energy += 0.5 * (u - u_rc);
                    for k in 0..3 {
                        forces[i][k] += du * d[k];
                    }
                }
                if !next_translation(&mut t, &n_max) {
                    break;
                }
            }
        }

        (energy, forces)
    }

    /// Lennard-Jones parameters of the fixture (see `oracle_ase.py`).
    const SIGMA: f64 = 1.0;
    const EPSILON: f64 = 1.0;
    const RC: f64 = 1.21;

    /// Energy/force callback for the Lennard-Jones model.
    fn lj_energy_fn(
        _elements: &[u8],
        positions: &[[f64; 3]],
        lattice: &[[f64; 3]; 3],
    ) -> Result<(f64, Vec<[f64; 3]>), String> {
        let (e, f) = lj_energy_forces(positions, lattice, SIGMA, EPSILON, RC);
        Ok((e, f))
    }

    /// sci-form's numerical stress must agree with ASE's Lennard-Jones
    /// stress (same convention: `sigma_ij = (1/V) dE/deps_ij`), and the
    /// variable-cell relaxation must recover the lattice constant that ASE
    /// finds for the same model.
    #[test]
    fn f85_variable_cell_stress_matches_ase() {
        let fixture: Fixture = load("ase_stress.json");
        assert!(fixture.cases.len() >= 3, "corpus too small");

        let mut worst_stress = (0.0f64, String::new());
        let mut worst_energy = 0.0f64;
        let mut worst_lattice = 0.0f64;

        for case in &fixture.cases {
            assert!(
                (case.sigma - SIGMA).abs() < 1e-12
                    && (case.epsilon - EPSILON).abs() < 1e-12
                    && (case.rc - RC).abs() < 1e-12,
                "{}: fixture parameters differ from the model constants",
                case.name
            );
            let elements = vec![18u8; case.positions.len()];
            let (energy, _forces) = lj_energy_forces(
                &case.positions,
                &case.lattice,
                case.sigma,
                case.epsilon,
                case.rc,
            );
            worst_energy = worst_energy.max((energy - case.energy_ev).abs());

            let model: &CellEnergyForceFn = &lj_energy_fn;

            let stress = numerical_stress(&elements, &case.positions, &case.lattice, &model, 1e-4)
                .expect("stress");

            for (row, ref_row) in stress.iter().zip(case.stress_ev_per_a3.iter()) {
                for (value, ref_value) in row.iter().zip(ref_row.iter()) {
                    let d = (value - ref_value).abs();
                    if d > worst_stress.0 {
                        worst_stress = (d, case.name.clone());
                    }
                }
            }

            // Variable-cell relaxation: the relaxed lattice constant must
            // match the one ASE finds for the same model.
            let config = VariableCellConfig {
                max_outer: 200,
                max_inner: 50,
                force_tol: 1e-6,
                stress_tol: 1e-8,
                strain_scale: 4.0,
                max_strain: 0.02,
                stress_delta: 1e-4,
            };
            let result =
                optimize_variable_cell(&elements, &case.positions, &case.lattice, &model, &config)
                    .expect("relaxation");
            let a_ours = result.lattice[0][0];
            let a_ref = case.relaxed_lattice[0];
            worst_lattice = worst_lattice.max((a_ours - a_ref).abs());
            println!(
                "  {:<12} E_ours={:.8} E_ase={:.8} | stress_max|Δ|={:.3e} | a_ours={:.6} a_ase={:.6}",
                case.name,
                energy,
                case.energy_ev,
                (0..3)
                    .map(|i| (stress[i][i] - case.stress_ev_per_a3[i][i]).abs())
                    .fold(0.0f64, f64::max),
                a_ours,
                a_ref
            );
        }

        println!(
            "F85 stress vs ASE: n={} worst |Δσ| = {:.3e} eV/A^3 ({}) | worst |ΔE| = {:.3e} eV \
             | worst |Δa| = {:.3e} A",
            fixture.cases.len(),
            worst_stress.0,
            worst_stress.1,
            worst_energy,
            worst_lattice
        );

        assert!(
            worst_energy <= 1e-9,
            "Lennard-Jones energy mismatch {:.3e} eV (model conventions differ)",
            worst_energy
        );
        assert!(
            worst_stress.0 <= 1e-5,
            "worst stress deviation {:.3e} eV/A^3 for {} (tolerance 1e-5)",
            worst_stress.0,
            worst_stress.1
        );
        assert!(
            worst_lattice <= 1e-3,
            "worst relaxed lattice constant deviation {:.3e} A (tolerance 1e-3)",
            worst_lattice
        );

        record(
            "F85",
            "variable_cell_stress_max_abs",
            "max_abs",
            worst_stress.0,
            1e-5,
            worst_stress.0 <= 1e-5,
            fixture.cases.len(),
        );
        record(
            "F85",
            "variable_cell_relaxed_lattice_max_abs",
            "max_abs",
            worst_lattice,
            1e-3,
            worst_lattice <= 1e-3,
            fixture.cases.len(),
        );
    }
}
